// @FIGURE_CODE_BEGIN
/* ───────────── graph data & layout (textbook CLRS fig. 24.4) ───────────── */
var VERT = ['s', 't', 'x', 'y', 'z'];
var NODE = { s: { x: 74, y: 216 }, t: { x: 234, y: 74 }, x: { x: 502, y: 74 }, y: { x: 234, y: 324 }, z: { x: 502, y: 324 } };
var NAMEPOS = { s: [36, 220], t: [234, 32], x: [502, 32], y: [234, 374], z: [502, 374] };
var R = 26;
var GRAY_FILL = '#d4d4d4';
var HI_GRAY = '#a8a8a8';
var HI_W = 10;

/* edges listed in the fixed textbook relaxation order */
var EDGES = [
  { u: 't', v: 'x', w: 5, arc: 52, lab: [368, 24] },
  { u: 't', v: 'y', w: 8, lab: [210, 198], an: 'end' },
  { u: 't', v: 'z', w: -4, lab: [452, 214] },
  { u: 'x', v: 't', w: -2, arc: 46, lab: [368, 90] },
  { u: 'y', v: 'x', w: -3, lab: [452, 150] },
  { u: 'y', v: 'z', w: 9, lab: [368, 350] },
  { u: 'z', v: 'x', w: 7, lab: [530, 204], an: 'start' },
  { u: 'z', v: 's', w: 2, lab: [402, 268] },
  { u: 's', v: 't', w: 6, lab: [126, 128] },
  { u: 's', v: 'y', w: 7, lab: [126, 288] }
];
var EKEY = function (e) { return e.u + '\u2192' + e.v; };

/* ───────────── drawing scaffold ───────────── */
var gDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
gDraw.viewbox(0, 0, 570, 442);
var gHi = gDraw.group(), gEx = gDraw.group(), gEdge = gDraw.group(),
  gArrow = gDraw.group(), gHit = gDraw.group(), gNodeG = gDraw.group(), gLabel = gDraw.group();

function fmtD(v) {
  if (v === Infinity) return '\u221e';
  if (v === -Infinity) return '-\u221e';
  if (v < 0) return '\u2212' + Math.abs(v);
  return '' + v;
}

function mkText(parent, str, px, py, size, opts) {
  opts = opts || {};
  var t = parent.plain(str);
  t.font({ family: 'Georgia,"Times New Roman",serif', size: size, anchor: opts.anchor || 'middle' });
  if (opts.italic) t.font({ style: 'italic' });
  t.attr({ x: px, y: py, 'dominant-baseline': 'central' });
  if (opts.halo) t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
  return t;
}

function edgeGeom(e) {
  var A = NODE[e.u], B = NODE[e.v];
  var mx = (A.x + B.x) / 2, my = (A.y + B.y) / 2;
  var dx = B.x - A.x, dy = B.y - A.y, L = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / L, uy = dy / L, cx = mx, cy = my;
  if (e.arc) { cx = mx + uy * e.arc; cy = my - ux * e.arc; }
  var a1 = Math.atan2(cy - A.y, cx - A.x), a2 = Math.atan2(cy - B.y, cx - B.x);
  var sx = A.x + Math.cos(a1) * (R + 2), sy = A.y + Math.sin(a1) * (R + 2);
  var ex = B.x + Math.cos(a2) * (R + 2), ey = B.y + Math.sin(a2) * (R + 2);
  var d = e.arc ? ('M' + sx + ',' + sy + ' Q' + cx + ',' + cy + ' ' + ex + ',' + ey)
    : ('M' + sx + ',' + sy + ' L' + ex + ',' + ey);
  var dxr, dyr;
  if (e.arc) { dxr = ex - cx; dyr = ey - cy; } else { dxr = ux; dyr = uy; }
  var dl = Math.sqrt(dxr * dxr + dyr * dyr); dxr /= dl; dyr /= dl;
  var bx = ex - dxr * 11, by = ey - dyr * 11, px = -dyr * 4.6, py = dxr * 4.6;
  var arrow = [[ex, ey], [bx + px, by + py], [bx - px, by - py]];
  return { d: d, arrow: arrow };
}

var hiPath = [], exPath = [], edgePath = [], arrowPoly = [], labText = [], idxOf = {};
EDGES.forEach(function (e, i) {
  var g = edgeGeom(e);
  idxOf[EKEY(e)] = i;
  hiPath.push(gHi.path(g.d).fill('none').stroke({ color: HI_GRAY, width: HI_W, linecap: 'round', linejoin: 'round' }).attr('stroke-opacity', 0));
  exPath.push(gEx.path(g.d).fill('none').stroke({ color: '#2b7bd6', width: 5, linecap: 'round' }).attr('stroke-opacity', 0));
  edgePath.push(gEdge.path(g.d).fill('none').stroke({ color: '#000', width: 1.4, linecap: 'round' }));
  arrowPoly.push(gArrow.polygon(g.arrow.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill('#000'));
  labText.push(mkText(gLabel, fmtD(e.w), e.lab[0], e.lab[1], 17, { anchor: e.an || 'middle', halo: true }));
  var hit = gHit.path(g.d).fill('none').stroke({ color: '#000', width: 16, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip(edgeTip(e), ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Relaxing edge ' + e.u + '\u2192' + e.v + ' (w = ' + fmtD(e.w) + ')',
        'Relaxation asks one question: is d[' + e.u + '] + (' + fmtD(e.w) + ') smaller than the current estimate d[' + e.v + ']? If yes, d[' + e.v + '] is lowered and ' + e.u + ' becomes ' + e.v + '\u2019s predecessor (the bold gray edge). If no, nothing happens. Bellman\u2013Ford asks this for all 10 edges, 4 times in a row \u2014 nothing cleverer.');
    });
});

var circ = {}, valText = {}, ring = {};
VERT.forEach(function (n) {
  var p = NODE[n];
  ring[n] = gNodeG.circle(2 * (R + 5)).center(p.x, p.y).fill('none').stroke({ color: '#e07a00', width: 3 }).attr('stroke-opacity', 0);
  circ[n] = gNodeG.circle(2 * R).center(p.x, p.y).fill(GRAY_FILL).stroke({ color: '#000', width: 1.3 }).css('cursor', 'pointer');
  valText[n] = mkText(gNodeG, '\u221e', p.x, p.y, 24, {});
  valText[n].css('pointer-events', 'none');
  mkText(gLabel, n, NAMEPOS[n][0], NAMEPOS[n][1], 19, { italic: true });
  circ[n].on('mousemove', function (ev) {
    showTooltip('d[' + n + '] = ' + fmtD(curState.dist[n]) + '   \u00b7   predecessor: ' + (curState.pred[n] || '\u2014'), ev);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Vertex ' + n,
        'The number inside a vertex is d[' + n + '], the best known upper bound on the shortest-path weight from s. It starts at \u221e (0 for the source) and only ever goes down, as relaxations discover cheaper routes. Its predecessor pointer names the last edge on that best-known route.');
    });
});

/* panel caption, exactly as in the textbook figure */
var capText = mkText(gLabel, '(a)', 288, 418, 22, {});

/* ───────────── reference simulation (panels a–e) ───────────── */
function simulate() {
