  var sn = SNAPS[k];
  renderState(passState(k));
  var r = document.getElementById('passReadout');
  if (k === 0) r.textContent = 'Panel (a) \u2014 initialization: d[s] = 0, every other estimate \u221e.';
  else r.textContent = 'Panel ' + PANEL[k] + ' \u2014 pass ' + k + ' of 4: ' + sn.changed.length + ' estimate' + (sn.changed.length === 1 ? '' : 's') + ' lowered'
    + (sn.changed.length ? ' (' + sn.changed.join(', ') + ')' : '') + ', ' + sn.fired + ' successful relaxation' + (sn.fired === 1 ? '' : 's') + '.';
}

/* ───────────── controls: pass stepper & highlight toggle ───────────── */
var PASSNAME = ['init', 'pass1', 'pass2', 'pass3', 'pass4'];
function set_passStepper(v) {
  stopPlay();
  mode = 'passes';
  currentPass = Math.max(0, PASSNAME.indexOf(v));
  document.getElementById('passStepperInput').value = PASSNAME[currentPass];
  renderPass(currentPass);
}
function toggle_showTree(on) {
  treeMode = !!on;
  document.getElementById('showTreeInput').checked = treeMode;
  if (mode === 'replay') renderFrame(frameIdx); else renderPass(currentPass);
}

/* ───────────── demo steps ───────────── */
var STEPS = [
  { t: 'Initialization \u2014 panel (a)', n: 'Every vertex starts at \u221e except the source s, which is 0. No edge is highlighted yet \u2014 the algorithm knows nothing but where it began.', p: 'init', tree: false },
  { t: 'Pass 1 \u2014 only s\u2019s neighbours can improve, panel (b)', n: 'Sweeping all ten edges, only the edges leaving s find a finite d[u], so d[t]=6 and d[y]=7. The eight edges examined earlier in the order did nothing, because their tails were still \u221e. The heavy gray edges are the predecessor tree so far.', p: 'pass1', tree: false },
  { t: 'Pass 2 \u2014 the frontier advances, panel (c)', n: 'Now t and y are finite: t\u2192x first sets d[x]=11, then y\u2192x improves it to 4, and t\u2192z gives d[z]=2. The tree re-roots x under y \u2014 information has travelled one more edge outward.', p: 'pass2', tree: false },
  { t: 'Pass 3 \u2014 a negative edge pulls an estimate down, panel (d)', n: 'The negative edge x\u2192t lowers d[t] from 6 to 2, so t\u2019s predecessor switches from s to x. Because t\u2192z was examined earlier in this same sweep, d[z] must wait for the next pass. Estimates go down, they are not merely filled in.', p: 'pass3', tree: false },
  { t: 'Pass 4 \u2014 convergence, panel (e)', n: 'With d[t]=2 available, t\u2192z finally drops d[z] to \u22122. The values 0, 2, 4, 7, \u22122 are final and the heavy gray predecessor edges spell out the shortest-path tree s\u2192y\u2192x\u2192t\u2192z; another sweep would change nothing.', p: 'pass4', tree: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.t + '</b><br>' + s.n;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  document.getElementById('showTreeInput').checked = s.tree;
  treeMode = s.tree;
  document.getElementById('passStepperInput').value = s.p;
  set_passStepper(s.p);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ───────────── code workbench ───────────── */
var SAMPLES = {
  sample: '// Called once per edge, in the fixed order, for each of 4 passes.\n// d[s] starts at 0; every other vertex starts at Infinity.\nfunction relax(u, v, w) {\n  if (dist(u) + w < dist(v)) {\n    setDist(v, dist(u) + w);\n    setPred(v, u);\n    note(u + \' improves \' + v + \' to \' + dist(v));\n  }\n}',
  buggy: 'function relax(u, v, w) {\n  // BUG: compares only the edge weight, forgetting the cost of reaching u.\n  // Watch z settle at 2 instead of -2, and x never reach 4.\n  if (w < dist(v)) {\n    setDist(v, w);\n    setPred(v, u);\n  }\n}',
  blank: 'function relax(u, v, w) {\n  // your code here: lower d[v] if going through u is cheaper\n}'
};
function loadSample(which) {
  document.getElementById('relaxEditorCode').value = SAMPLES[which];
  ['tabSample', 'tabBuggy', 'tabBlank'].forEach(function (id) { document.getElementById(id).classList.remove('active'); });
  document.getElementById({ sample: 'tabSample', buggy: 'tabBuggy', blank: 'tabBlank' }[which]).classList.add('active');
}

function edgeTip(e) {
  var du = curState.dist[e.u], dv = curState.dist[e.v], sum = du + e.w;
  return e.u + '\u2192' + e.v + ',  w = ' + fmtD(e.w) + '   |   d[' + e.u + ']+w = ' + fmtD(sum) +
    (sum < dv ? ' < ' : ' \u2265 ') + 'd[' + e.v + '] = ' + fmtD(dv) + (sum < dv ? '  \u2192 relaxes!' : '  \u2192 no change');
}

function parseOrder(src) {
  var re = /\(\s*([A-Za-z])\s*,\s*([A-Za-z])\s*,\s*[\u2212-]?\s*\d+\s*\)/g, m, out = [];
  while ((m = re.exec(src))) {
    var u = m[1], v = m[2], found = null;
    for (var i = 0; i < EDGES.length; i++) if (EDGES[i].u === u && EDGES[i].v === v) found = EDGES[i];
    if (!found) return { error: 'There is no edge ' + u + '\u2192' + v + ' in this graph.' };
    out.push({ u: u, v: v, w: found.w });
  }
  if (!out.length) return { error: 'Could not read any (u,v,w) triples from the order.' };
  return { edges: out };
}

/* worker body — student code never touches the main thread */
function bfWorkerMain() {
  function fmt(v) { return v === Infinity ? '\u221e' : (v < 0 ? '\u2212' + Math.abs(v) : '' + v); }
  self.onmessage = function (ev) {
    var d = ev.data, edges = d.edges, passes = d.passes;
    var dist = {}, pred = {}, frames = [], ops = 0, cur = -1, pass = 0;
    var MAXOPS = 20000, MAXFRAMES = 2500, T0 = Date.now(), TLIMIT = 1500;
    d.vertices.forEach(function (v) { dist[v] = (v === d.source) ? 0 : Infinity; });
    function cp(o) { var r = {}; for (var k in o) r[k] = o[k]; return r; }
    function frame(kind, indices, message) {
      if (frames.length >= MAXFRAMES) throw new Error('frame cap (' + MAXFRAMES + ') reached \u2014 far too many recorded steps.');
      frames.push({ kind: kind, dist: cp(dist), pred: cp(pred), edge: cur, pass: pass, indices: indices || [], message: message || '' });
    }
    function guard(name) {
      ops++;
      if (ops > MAXOPS) throw new Error('operation cap (' + MAXOPS + ') reached inside ' + name + '() \u2014 probably an endless loop.');
      if (Date.now() - T0 > TLIMIT) throw new Error('time limit (' + TLIMIT + ' ms) exceeded inside ' + name + '().');
    }
    function vchk(name, v) { v = String(v); if (!(v in dist)) throw new Error(name + ': unknown vertex "' + v + '" (use s, t, x, y or z).'); return v; }
    function a_dist(v) { guard('dist'); return dist[vchk('dist', v)]; }
    function a_setDist(v, val) {
      guard('setDist'); v = vchk('setDist', v);
      if (typeof val !== 'number' || isNaN(val)) throw new Error('setDist(' + v + ', \u2026) needs a number.');
      var old = dist[v]; dist[v] = val;
      frame('setDist', [v], 'd[' + v + '] \u2190 ' + fmt(val) + '   (was ' + fmt(old) + ')');
    }
    function a_setPred(v, u) {
      guard('setPred'); v = vchk('setPred', v); u = vchk('setPred', u); pred[v] = u;
      frame('setPred', [u, v], 'pred[' + v + '] \u2190 ' + u + '  \u2014 edge ' + u + '\u2192' + v + ' joins the tree');
    }
    function a_weightOf(u, v) {
      guard('weightOf'); u = vchk('weightOf', u); v = vchk('weightOf', v);
      for (var i = 0; i < edges.length; i++) if (edges[i].u === u && edges[i].v === v) return edges[i].w;
      throw new Error('weightOf: there is no edge ' + u + '\u2192' + v + '.');
    }
    function a_note(t) { guard('note'); frame('note', [], String(t)); }
    var userFn = null, fatal = null;
    try {
      userFn = new Function('dist', 'setDist', 'setPred', 'weightOf', 'note',
        '"use strict";\n' + d.code + '\n;return typeof relax === "function" ? relax : null;')(a_dist, a_setDist, a_setPred, a_weightOf, a_note);
    } catch (e) { fatal = 'Syntax error: ' + ((e && e.message) ? e.message : e); }
    if (!fatal && !userFn) fatal = 'No function named relax(u, v, w) was found. Define:  function relax(u, v, w) { \u2026 }';
    frames.push({ kind: 'init', dist: cp(dist), pred: cp(pred), edge: -1, pass: 0, indices: [], message: 'Initialization: d[' + d.source + '] = 0, every other estimate = \u221e.' });
    if (fatal) {
      frames.push({ kind: 'error', dist: cp(dist), pred: cp(pred), edge: -1, pass: 0, indices: [], message: fatal });
      self.postMessage({ frames: frames, status: 'error', message: fatal, wrong: [], violations: [] }); return;
    }
    var stopped = null;
    for (pass = 1; pass <= passes && !stopped; pass++) {
      var before = cp(dist);
      try { frame('pass', [], 'Pass ' + pass + ' of ' + passes + ' \u2014 sweep all ' + edges.length + ' edges in the fixed order.'); }
      catch (e0) { stopped = e0.message; break; }
      for (var i = 0; i < edges.length; i++) {
        cur = i; var e = edges[i];
        try {
          frame('examine', [e.u, e.v], 'Pass ' + pass + ': examine ' + e.u + '\u2192' + e.v + ' (w = ' + fmt(e.w) + ') \u2014 d[' + e.u + '] = ' + fmt(dist[e.u]) + ', d[' + e.v + '] = ' + fmt(dist[e.v]));
          userFn(e.u, e.v, e.w);
        } catch (err) { stopped = (err && err.message) ? err.message : String(err); break; }
      }
      cur = -1;
      if (stopped) break;
      var ch = []; for (var k in dist) if (dist[k] !== before[k]) ch.push(k);
      try {
        frame('passEnd', ch, 'End of pass ' + pass + ': ' + (ch.length ? ch.length + ' estimate' + (ch.length > 1 ? 's' : '') + ' lowered (' + ch.join(', ') + ')' : 'nothing changed \u2014 converged'));
      } catch (e1) { stopped = e1.message; break; }
    }
    pass = passes;
    if (stopped) {
      frames.push({ kind: 'error', dist: cp(dist), pred: cp(pred), edge: cur, pass: pass, indices: [], message: 'Run stopped: ' + stopped });
      self.postMessage({ frames: frames, status: 'error', message: stopped, wrong: [], violations: [] }); return;
    }
    var wrong = [], viol = [];
    for (var v2 in d.expected) if (dist[v2] !== d.expected[v2]) wrong.push(v2);
    for (var j = 0; j < edges.length; j++) { var ee = edges[j]; if (dist[ee.u] + ee.w < dist[ee.v]) viol.push(ee.u + '\u2192' + ee.v); }
    var ok = (wrong.length === 0 && viol.length === 0);
    frames.push({
      kind: ok ? 'done' : 'wrong', dist: cp(dist), pred: cp(pred), edge: -1, pass: pass,
      indices: ok ? [] : wrong, message: ok
        ? 'Converged: every estimate is final and no edge can be relaxed any further.'
        : 'Not shortest paths: wrong at ' + (wrong.length ? wrong.join(', ') : '(values look right)') + (viol.length ? '; still relaxable: ' + viol.join(', ') : '')
    });
    self.postMessage({ frames: frames, status: ok ? 'correct' : 'wrong', message: ok ? 'correct' : 'wrong answer', wrong: wrong, violations: viol });
  };
}

var frames = [], frameIdx = 0, runOrder = EDGES.slice(), running = false, lastResult = null;
function setStatus(kind, msg) {
  var el = document.getElementById('runStatus');
  var col = { 'notrun': '#666', 'running': '#b06000', 'correct': '#1a7f37', 'wrong': '#b3261e', 'error': '#b3261e' }[kind] || '#666';
  el.style.color = col; el.textContent = msg;
}
setStatus('notrun', 'not run');

function trigger_relaxEditor() {
  if (running) return;
  var errSlot = document.getElementById('orderErr');
  var ord = parseOrder(document.getElementById('relaxEditorInput').value);
  if (ord.error) { errSlot.textContent = ord.error; errSlot.style.display = ''; setStatus('error', 'bad edge order'); return; }
  errSlot.style.display = 'none';
  runOrder = ord.edges;
  running = true;
  document.getElementById('runBtn').disabled = true;
  setStatus('running', 'running in sandbox\u2026');
  var src = '(' + bfWorkerMain.toString() + ')()';
  var url = URL.createObjectURL(new Blob([src], { type: 'application/javascript' }));
  var w = new Worker(url);
  var finish = function () { try { w.terminate(); } catch (e) { } URL.revokeObjectURL(url); running = false; document.getElementById('runBtn').disabled = false; };
  var to = setTimeout(function () { finish(); setStatus('error', 'timed out (>2 s) \u2014 relax() never returned'); document.getElementById('frameCaption').textContent = 'Your relax() ran longer than 2 seconds; it probably loops forever.'; }, 2200);
  w.onmessage = function (ev) { clearTimeout(to); finish(); onResult(ev.data); };
  w.onerror = function (er) { clearTimeout(to); finish(); setStatus('error', 'worker error'); document.getElementById('frameCaption').textContent = er.message || 'Worker error'; };
  w.postMessage({ code: document.getElementById('relaxEditorCode').value, edges: runOrder, passes: 4, vertices: VERT, source: 's', expected: { s: 0, t: 2, x: 4, y: 7, z: -2 } });
}

function onResult(data) {
  lastResult = data;
  frames = data.frames || [];
  mode = 'replay';
  frameIdx = 0;
  if (data.status === 'correct') setStatus('correct', '\u2713 correct \u2014 all estimates final');
  else if (data.status === 'wrong') setStatus('wrong', '\u2717 wrong answer \u2014 see last frame');
  else setStatus('error', '\u26a0 error \u2014 see caption');
  renderFrame(0);
}

function renderFrame(i) {
  if (!frames.length) return;
  frameIdx = Math.max(0, Math.min(frames.length - 1, i));
  var f = frames[frameIdx];
  /* predecessor edges added during the CURRENT pass — used only for the
     brief fade-in cue; the drawn stroke is identical for every tree edge */
  var fresh = [];
  for (var k = 0; k <= frameIdx; k++) {
    var fr = frames[k];
    if (fr.kind === 'setPred' && fr.pass === f.pass) fresh.push(fr.indices[0] + '\u2192' + fr.indices[1]);
  }
  var strong = [];
  for (var v in f.pred) strong.push(f.pred[v] + '\u2192' + v);
  var exKey = (f.edge >= 0 && runOrder[f.edge]) ? (runOrder[f.edge].u + '\u2192' + runOrder[f.edge].v) : null;
  var bad = (f.kind === 'wrong' || f.kind === 'error');
  renderState({
    dist: f.dist, pred: f.pred, strong: strong, fresh: fresh, examine: exKey,
    dim: treeMode, mark: f.indices || [], markColor: bad ? '#c62828' : '#e07a00',
    panel: PANEL[Math.min(4, f.pass)] || '(a)'
  });
  document.getElementById('passStepperInput').value = PASSNAME[Math.min(4, f.pass)] || 'init';
  document.getElementById('passReadout').textContent = (f.pass ? 'Replay \u2014 pass ' + f.pass + ' of 4' : 'Replay \u2014 initialization') + '  (' + f.kind + ')';
  document.getElementById('frameCounter').textContent = (frameIdx + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var lines = [], start = Math.max(0, frameIdx - 39);
  for (var j = start; j <= frameIdx; j++) lines.push((j === frameIdx ? '\u25b6 ' : '  ') + (j + 1) + '. ' + frames[j].message);
  var logEl = document.getElementById('runLog');
  logEl.textContent = lines.join('\n');
  logEl.scrollTop = logEl.scrollHeight;
}

var playTimer = null, fps = 2;
function update_speed(v) { fps = v; if (playTimer) { stopPlay(); startPlay(); } }
function startPlay() {
  if (!frames.length) return;
  document.getElementById('playBtn').textContent = '\u23f8';
  playTimer = setInterval(function () {
    if (frameIdx >= frames.length - 1) { stopPlay(); return; }
    renderFrame(frameIdx + 1);
  }, Math.max(90, 1000 / fps));
}
function stopPlay() { if (playTimer) { clearInterval(playTimer); playTimer = null; } document.getElementById('playBtn').textContent = '\u25b6'; }
function replayToggle() { if (playTimer) stopPlay(); else { mode = 'replay'; startPlay(); } }
function replayFirst() { stopPlay(); if (frames.length) { mode = 'replay'; renderFrame(0); } }
function replayPrev() { stopPlay(); if (frames.length) { mode = 'replay'; renderFrame(frameIdx - 1); } }
function replayNext() { stopPlay(); if (frames.length) { mode = 'replay'; renderFrame(frameIdx + 1); } }

/* ───────────── boot ───────────── */
loadSample('sample');
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Bellman-Ford finds shortest paths by relaxing every edge once per pass, repeating |V|−1 times so that estimates (including ones lowered by negative-weight edges) propagate outward and converge.
KEY INSIGHT (what students should walk away understanding): One dumb rule — 'if going through u is cheaper, take it' — applied to every edge |V|−1 times is enough, because after k passes every vertex reachable by a k-edge shortest path has its final value, and negative edges simply keep pushing estimates downward until nothing improves.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Bellman-Ford finds shortest paths by relaxing every edge once per pass, repeating |V|−1 times so that estimates (including ones lowered by negative-weight edges) propagate outward and converge.",
  "figureType": "network_diagram",
  "elements": [
    "Five vertices drawn as gray-filled circles with black outlines: s (far left), t (upper center-left), y (lower center-left), x (upper right), z (lower right)",
    "Italic vertex name labels placed outside each circle: s left of its circle, t and x above, y and z below",
    "Shortest-path estimate d[v] printed inside each circle (0, ∞, or a number such as 6, 7, 4, 2, −2)",
    "Directed edge s→t with weight 6",
    "Directed edge s→y with weight 7",
    "Curved directed edge t→x with weight 5 (upper arc)",
    "Curved directed edge x→t with weight −2 (lower arc of the same pair)",
    "Directed edge t→y with weight 8 (vertical)",
    "Directed edge t→z with weight −4 (diagonal down-right)",
    "Directed edge y→x with weight −3 (diagonal up-right)",
    "Directed edge y→z with weight 9 (horizontal bottom)",
    "Directed edge z→x with weight 7 (vertical right)",
    "Directed edge z→s with weight 2 (long horizontal back to s)",
    "Numeric weight labels beside every edge, upright roman type",
    "Bold gray highlight stroke drawn underneath edges that successfully relaxed in the current pass (predecessor edges)",
    "Panel captions (a)–(e) in the static textbook version, corresponding to the initial state and the four relaxation passes",
    "A pass counter / status readout showing the current pass number and how many distance estimates changed"
  ],
  "interactions": [
    {
      "id": "relaxEditor",
      "type": "code_editor",
      "teaches": "That the entire Bellman-Ford algorithm is one tiny rule — relax(u,v,w) — applied blindly to every edge, pass after pass, and that the order of edges plus the guard condition determine exactly which estimates drop when.",
      "label": "Implement relax(u, v, w)",
      "entry_point": "relax(u, v, w)",
      "api": [
        {
          "op": "dist(v)",
          "does": "current shortest-path estimate d[v]; returns Infinity if not yet reached"
        },
        {
          "op": "setDist(v, value)",
          "does": "update d[v] — the ONLY way to change a distance; records a frame and animates the number inside vertex v"
        },
        {
          "op": "setPred(v, u)",
          "does": "record u as v's predecessor; shades edge u→v bold gray in the current pass"
        },
        {
          "op": "weightOf(u, v)",
          "does": "the weight w of edge u→v (also passed in as the third argument)"
        },
        {
          "op": "note(text)",
          "does": "attach your own commentary to the current frame, shown in the replay caption"
        }
      ],
      "frame": "the whole 5-vertex graph: every d[v] inside its circle, the edge just examined outlined, and edges whose relaxation succeeded shaded bold gray",
      "input": {
        "label": "Edge relaxation order (fixed, as in the textbook)",
        "default": "(t,x,5), (t,y,8), (t,z,-4), (x,t,-2), (y,x,-3), (y,z,9), (z,x,7), (z,s,2), (s,t,6), (s,y,7)"
      },
      "sample_code": "// Called once per edge, in the fixed order, for each of 4 passes.\n// dist.s starts at 0; every other vertex starts at Infinity.\nfunction relax(u, v, w) {\n  if (dist(u) + w < dist(v)) {\n    setDist(v, dist(u) + w);\n    setPred(v, u);\n    note(u + ' improves ' + v + ' to ' + (dist(u) + w));\n  }\n}",
      "buggy_code": "function relax(u, v, w) {\n  // BUG: compares only the edge weight, forgetting the cost of getting to u.\n  // Watch z get 2 instead of -2, and x never settle at 4.\n  if (w < dist(v)) {\n    setDist(v, w);\n    setPred(v, u);\n  }\n}",
      "success_check": "After 4 passes: d[s]=0, d[t]=2, d[x]=4, d[y]=7, d[z]=−2, and no further relaxation changes any estimate."
    },
    {
      "id": "passStepper",
      "type": "state",
      "teaches": "That each panel of the figure is exactly one complete sweep over all ten edges, and that the number of estimates that improve shrinks to zero as the algorithm converges.",
      "label": "Relaxation pass",
      "states": [
        "init",
        "pass1",
        "pass2",
        "pass3",
        "pass4"
      ],
      "default": "init"
    },
    {
      "id": "showTree",
      "type": "toggle",
      "teaches": "That the bold gray edges are not just 'recently changed' edges but the predecessor pointers that together form the shortest-path tree rooted at s.",
      "label": "Highlight",
      "options": [
        "this pass's relaxations",
        "shortest-path tree"
      ],
      "default": "this pass's relaxations"
    }
  ],
  "demo_steps": [
    {
      "title": "Initialization (panel a)",
      "narration": "Every vertex starts at ∞ except the source s, which is 0. No edge is highlighted yet — the algorithm knows nothing but where it began.",
      "state": {
        "passStepper": "init",
        "showTree": "this pass's relaxations"
      }
    },
    {
      "title": "Pass 1 — only s's neighbors can improve (panel b)",
      "narration": "Sweeping all ten edges, only edges leaving s find a finite dist(u), so d[t]=6 and d[y]=7. Two estimates changed; all the edges examined earlier in the order were useless because their tails were still ∞.",
      "state": {
        "passStepper": "pass1",
        "showTree": "this pass's relaxations"
      }
    },
    {
      "title": "Pass 2 — the frontier advances (panel c)",
      "narration": "Now t and y are finite, so y→x gives d[x]=4 and t→z gives d[z]=2. Two more changes: information has travelled one more edge outward.",
      "state": {
        "passStepper": "pass2",
        "showTree": "this pass's relaxations"
      }
    },
    {
      "title": "Pass 3 — negative edges pull estimates down (panel d)",
      "narration": "The negative edge x→t lowers d[t] from 6 to 2, which immediately lets t→z lower d[z] from 2 to −2. Estimates can go down, not just be filled in.",
      "state": {
        "passStepper": "pass3",
        "showTree": "this pass's relaxations"
      }
    },
    {
      "title": "Pass 4 — convergence (panel e)",
      "narration": "A full sweep changes nothing: the counter reads 0. The bold edges now spell out the shortest-path tree s → y → x → t → z with final values 0, 7, 4, 2, −2.",
      "state": {
        "passStepper": "pass4",
        "showTree": "shortest-path tree"
      }
    }
